  "claims": [
    {
      "kind": "quantitative",
      "text": "Kohl's generated revenue of {{m:revenue:FY-2}} in {{p:FY-2}}, {{m:revenue:FY-1}} in {{p:FY-1}}, {{m:revenue:FY0}} in {{p:FY0}}, and {{m:revenue:LTM}} in {{p:LTM}}.",
